-- ---------------------------------------------------------------------------
-- S-09 PendingAuthorizations demo data: the DBPAUTP0 hierarchy (PAUTSUM0 root,
-- PAUTDTL1 children) for two of the seeded accounts, so CPVS/CPVD have
-- something to browse and the stream's tests have a fixed oracle.
--
-- app/data/ASCII/** carries no PAUT unload — the estate only ships the EBCDIC
-- IMS image — so these rows are derived from CIPAUSMY/CIPAUDTY field by field
-- rather than converted from a fixture (boundary decision BD-8).
--
-- The child key is the IMS sequence field PAUT9CTS, i.e. the 9s complements
--   pa_auth_date_9c = 99999     - YYDDD          (2025-01-15 -> 25015 -> 74984)
--   pa_auth_time_9c = 999999999 - HHMMSSmmm
-- so ascending key order is most-recent-first, the order GNP returns.
-- Runs after R__seed_carddemo_data.sql (which clears these tables) because
-- Flyway orders repeatable migrations by description.
-- ---------------------------------------------------------------------------

INSERT INTO pending_auth_summary (pa_acct_id, pa_cust_id, pa_auth_status, pa_account_status_1, pa_account_status_2, pa_account_status_3, pa_account_status_4, pa_account_status_5, pa_credit_limit, pa_cash_limit, pa_credit_balance, pa_cash_balance, pa_approved_auth_cnt, pa_declined_auth_cnt, pa_approved_auth_amt, pa_declined_auth_amt) VALUES (1, 1, 'A', 'AC', '  ', '  ', '  ', '  ', 2020.00, 1020.00, 262.55, 0.00, 6, 1, 262.55, 500.00);
